def blank_matrix(ws, maxrow, maxcol):
    # precompute None grid 1-indexed
    grid=[[False]*(maxcol+1) for _ in range(maxrow+1)]
    for r in range(1,maxrow+1):
        for c in range(1,maxcol+1):
            grid[r][c]=(ws.cell(r,c).value is None)
    return grid
g1=blank_matrix(ws1,49,20); g2=blank_matrix(ws2,77,19)

def count(grid,r1,r2,c1,c2):
    return sum(grid[r][c] for r in range(r1,r2+1) for c in range(c1,c2+1))

# generate counts for all rectangles in sheet1 within rows 1..49, cols 1..20, top<=12, bottom between 42 and 49, area etc.
